"""
Library Catalogue System

This module contains classes for managing a library catalogue including Books, Members,
and Loans. It supports searching books by author or title and includes overdue detection
and fine calculation.
"""

from datetime import date, timedelta

class Book:
    """Represents a book in the library catalogue."""
    def __init__(self, isbn, title, author, year, copies=1):
        self.isbn = isbn
        self.title = title
        self.author = author
        self.year = year
        self.copies = copies
        self.available_copies = copies

    def __str__(self):
        return f"{self.title} by {self.author} ({self.year}) ISBN: {self.isbn}"

class Member:
    """Represents a member of the library."""
    def __init__(self, member_id, name):
        self.member_id = member_id
        self.name = name
        self.loans = []  # list of Loan objects

    def __str__(self):
        return f"Member {self.name} ({self.member_id})"

class Loan:
    """Represents a loan of a book to a member."""
    def __init__(self, book, member, loan_date, due_days):
        self.book = book
        self.member = member
        self.loan_date = loan_date
        self.due_date = loan_date + timedelta(days=due_days)
        self.return_date = None

    def is_overdue(self, on_date=None):
        if self.return_date is not None:
            return False
        if on_date is None:
            on_date = date.today()
        return on_date > self.due_date

    def calculate_fine(self, fine_per_day):
        if self.return_date is None:
            on_date = date.today()
        else:
            on_date = self.return_date
        if on_date <= self.due_date:
            return 0
        delta = (on_date - self.due_date).days
        return delta * fine_per_day

class LibraryCatalogue:
    """Manages the entire library catalogue, members and loans."""
    def __init__(self, config):
        self.books = {}  # isbn -> Book
        self.members = {}  # member_id -> Member
        self.loans = []
        self.config = config

    def add_book(self, book):
        if book.isbn in self.books:
            self.books[book.isbn].copies += book.copies
            self.books[book.isbn].available_copies += book.copies
        else:
            self.books[book.isbn] = book

    def add_member(self, member):
        if member.member_id not in self.members:
            self.members[member.member_id] = member

    def loan_book(self, isbn, member_id, loan_date):
        if isbn not in self.books:
            raise ValueError(f"Book with ISBN {isbn} not found")
        if member_id not in self.members:
            raise ValueError(f"Member with ID {member_id} not found")
        book = self.books[isbn]
        member = self.members[member_id]

        if book.available_copies < 1:
            raise ValueError(f"No available copies of {book.title}")
        loan_days = self.config.get("default_loan_days", 14)
        loan = Loan(book, member, loan_date, loan_days)
        self.loans.append(loan)
        member.loans.append(loan)
        book.available_copies -= 1
        return loan

    def return_book(self, loan, return_date):
        if loan not in self.loans:
            raise ValueError("Invalid loan")
        if loan.return_date is not None:
            raise ValueError("Book already returned")
        loan.return_date = return_date
        loan.book.available_copies += 1

    def search_books(self, keyword):
        """Search books by title or author containing the keyword (case-insensitive)."""
        keyword = keyword.lower()
        result = []
        for book in self.books.values():
            if keyword in book.title.lower() or keyword in book.author.lower():
                result.append(book)
        return result

    def get_overdue_loans(self, on_date=None):
        if on_date is None:
            on_date = date.today()
        overdue = []
        for loan in self.loans:
            if loan.is_overdue(on_date):
                overdue.append(loan)
        return overdue

    def calculate_fines(self, on_date=None):
        if on_date is None:
            on_date = date.today()
        fine_per_day = self.config.get("fine_per_day", 0.5)
        fines = {}
        for loan in self.get_overdue_loans(on_date):
            fine = loan.calculate_fine(fine_per_day)
            fines[loan] = fine
        return fines
